from z3 import *

# Helper function to express gcd equals 1 using Z3
def gcd_is_one(x, y):
    return And(ForAll([Int('d')], Implies(And(Int('d') > 1, Int('d') <= Min(x, y)), Or(x % Int('d') != 0, y % Int('d') != 0))))

# Declare 14 integer variables
a = [Int(f'a{i}') for i in range(1, 15)]

# Create a solver instance
s = Solver()

# Add constraints for positivity
for ai in a:
    s.add(ai > 0)

# Add constraints for gcd conditions
for i in range(len(a)-1):
    s.add(gcd_is_one(a[i], a[i+1]))
for i in range(len(a)-2):
    s.add(gcd_is_one(a[i], a[i+2]))

# Add constraints for sums being composite numbers
# Since direct composite check isn't straightforward, let's use a heuristic: sums must be greater than 4 and not prime
def is_composite(n):
    return And(n > 4, Not(IsPrime(n)))

# Constraints for sums
for r in range(len(a)):
    for s in range(r, len(a)):
        sub_sum = Sum(a[r:s+1])
        s.add(is_composite(sub_sum))

# Check for satisfiability
if s.check() == sat:
    m = s.model()
    result = [m[ai].as_long() for ai in a]
    print(result)
else:
    print("unsat")
